import pandas as pd

def fit(d):
    a = d["area"]
    return {"area_median": float(a.median()), "lo": float(a.min()), "hi": float(a.max())}

def dedupe(d, f):
    out = d.drop_duplicates()
    return out, {"step": "dedupe", "rows_in": len(d), "rows_out": len(out), "cells": 0}

def fill_area(d, f):
    n = int(d["area"].isna().sum())
    out = d.assign(area=d["area"].fillna(f["area_median"]))
    return out, {"step": "fill_area", "rows_in": len(d), "rows_out": len(out), "cells": n}

def scale_area(d, f):
    a = (d["area"] - f["lo"]) / (f["hi"] - f["lo"])
    return d.assign(area01=a.round(3)), {"step": "scale_area", "rows_in": len(d), "rows_out": len(d), "cells": len(d)}

PIPELINE = [dedupe, fill_area, scale_area]

def run(d, fitted=None):
    log = []
    if fitted is None:
        fitted = fit(d.drop_duplicates())
    for step in PIPELINE:
        d, row = step(d, fitted)
        log.append(row)
    assert d["area01"].notna().all(), "blank cells in the output"
    return d, pd.DataFrame(log), fitted

march = pd.read_csv("march.csv")
X, report, fitted = run(march)
print(report.to_string(index=False))
print("fitted:", fitted)
june = pd.read_csv("june.csv")
Y, report2, _ = run(june, fitted)
print(report2.to_string(index=False))
print("same columns:", list(X.columns) == list(Y.columns))
print("June outside [0, 1]:", int(((Y["area01"] < 0) | (Y["area01"] > 1)).sum()))
